# ---------- MCP connection helpers ----------
async def _call_mcp_tool_async(tool_name: str, arguments: dict[str, Any]) -> Any:
    from mcp import ClientSession
    from mcp.client.streamable_http import streamablehttp_client
    async with streamablehttp_client(MCP_SERVER_URL) as (read_stream, write_stream, _):
        async with ClientSession(read_stream, write_stream) as session:
            await session.initialize()
            return await session.call_tool(tool_name, arguments=arguments)


def _decode_mcp_result(result: Any) -> Any:
    if getattr(result, "isError", False):
        texts = [getattr(item, "text", "") for item in (getattr(result, "content", None) or [])]
        raise RuntimeError(" ".join(texts) or "MCP tool returned an error.")
    for item in (getattr(result, "content", None) or []):
        text = getattr(item, "text", None)
        if text:
            try:
                return json.loads(text)
            except json.JSONDecodeError:
                return {"answer": text}
    structured = getattr(result, "structuredContent", None)
    return structured if structured is not None else {}


def call_mcp_tool(tool_name: str, arguments: dict[str, Any]) -> Any:
    return _decode_mcp_result(asyncio.run(_call_mcp_tool_async(tool_name, arguments)))


def backend_status() -> bool:
    async def check() -> None:
        from mcp import ClientSession
        from mcp.client.streamable_http import streamablehttp_client
        async with streamablehttp_client(MCP_SERVER_URL) as (read_stream, write_stream, _):
            async with ClientSession(read_stream, write_stream) as session:
                await session.initialize()
                await session.list_tools()
    try:
        asyncio.run(check())
        return True
    except Exception:
        return False


def load_tasks() -> list[dict[str, Any]]:
    try:
        result = call_mcp_tool("list_tasks", {})
        if isinstance(result, dict):
            tasks = result.get("tasks", [])
            if isinstance(tasks, list):
                return tasks
        if isinstance(result, list):
            return result
    except Exception:
        pass
    return []


def task_id(task: dict[str, Any]) -> Any:
    return task.get("id", task.get("task_id"))


def is_completed(task: dict[str, Any]) -> bool:
    return str(task.get("status", "pending")).strip().lower() in {"complete", "completed", "done"}


def parse_due(value: Any) -> date | None:
    if not value:
        return None
    try:
        return date.fromisoformat(str(value)[:10])
    except (ValueError, TypeError):
        return None


def navigate(page_name: str) -> None:
    st.session_state["navigation_page"] = page_name
    st.rerun()

